target_file = r'd:\Projects\HoN_RU_Pack\bundle\entities_en.str'
with open(target_file, 'rb') as f:
    text = f.read().decode('utf-8')

lines = text.split('\r\n')
count = 0
for i, line in enumerate(lines):
    if '\t' in line:
        k = line.split('\t')[0]
        if k in amun_ra_translations:
            # Reconstruct with the same exact tabs
            parts = line.split('\t')
            # Extract whitespace/tabs strictly following the key
            whitespace = line[len(k):line.find(parts[-1])]
            new_val = amun_ra_translations[k]
            lines[i] = f"{k}{whitespace}{new_val}"
            count += 1

with open(target_file, 'wb') as f:
    f.write('\r\n'.join(lines).encode('utf-8'))

print(f"Replaced {count} Amun-Ra keys in entities_en.str!")
